INSERT INTO feature VALUES('located-judgements','sessions','Located judgements over declared worlds','session-types','implemented','unique','mainstream languages','A source declares its worlds (world w ;); typing stands at one; A at w is a handle to a value at w; hold, let x at w = h and migrate [w] { t } make, open and cross, an opening writing the world its handle stands at; a migration spends the consumable capability cap_w its entry holds (@[ entry(home, w, …) ] bounded by the host''s --entry); only what is mobile (mobile type T at sealing) and open comes back.','core-term core-checker','corpus/model/worlds/seat-and-operator.gandr corpus/pathological/worlds/immobile-crossing.gandr corpus/pathological/worlds/capability-accounting.gandr corpus/pathological/worlds/located-reads.gandr','corpus/model/worlds/seat-and-operator.gandr','#521');
